script:
(function () {
  'use strict';
  // Pivot points from the previous period's high (H), low (L), close (C) and open (O).
  // Formulas checked against TradingView's "Pivot Points Standard" help page (Traditional,
  // Fibonacci, Woodie, DeMark, Camarilla) in this session. Range = H - L.
  //   Classic / floor: P = (H+L+C)/3; R1 = 2P-L; S1 = 2P-H; R2 = P+range; S2 = P-range;
  //                    R3 = H+2(P-L); S3 = L-2(H-P)
  //   Woodie:          P = (H+L+2C)/4 (close-weighted form); R1 = 2P-L; S1 = 2P-H; R2 = P+range;
  //                    S2 = P-range; R3 = H+2(P-L); S3 = L-2(H-P); R4 = R3+range; S4 = S3-range
  //                    (TradingView puts the current session's open in place of C; optional input.)
  //   Camarilla:       P = (H+L+C)/3; Rn = C + range x 1.1/k, Sn = C - range x 1.1/k, k = 12, 6, 4, 2
  //   Fibonacci:       P = (H+L+C)/3; R/S1 = P +/- 0.382 range; R/S2 = P +/- 0.618 range; R/S3 = P +/- range
  //   DeMark:          X = H+L+2C if C = O; 2H+L+C if C > O; H+2L+C if C < O
  //                    P = X/4; R1 = X/2 - L; S1 = X/2 - H
  // Verified (scratch Node test): H 110, L 100, C 105, O 102 -> classic P 105, R1 110, S1 100, R2 115,
  // S2 95, R3 120, S3 90; Woodie P 105; Camarilla R1 105.92, R4 110.50, S4 99.50; Fibonacci R1 108.82,
  // S2 98.82; DeMark (C > O) X 425, P 106.25, R1 112.50, S1 102.50. H 52.40, L 50.10, C 50.60, O 51.90 ->
  // classic P 51.03, R1 51.97, S1 49.67; DeMark (C < O) X 203.20, P 50.80, R1 51.50, S1 49.20.
  var ROWS = ['R4', 'R3', 'R2', 'R1', 'P', 'S1', 'S2', 'S3', 'S4'];
  var METHODS = [
    { key: 'classic', name: 'Classic' },
    { key: 'woodie', name: 'Woodie' },
    { key: 'camarilla', name: 'Camarilla' },
    { key: 'fibonacci', name: 'Fibonacci' },
    { key: 'demark', name: 'DeMark' }
  ];

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function blank(id) {
    var el = document.getElementById(id);
    return !el || String(el.value || '').trim() === '';
  }
  function decimalsOf(id) {
    var el = document.getElementById(id);
    var s = el ? String(el.value || '') : '';
    var i = s.indexOf('.');
    return i < 0 ? 0 : Math.min(6, s.length - i - 1);
  }
  function fmt(v, dp) {
    if (typeof v !== 'number' || !isFinite(v)) return '–';
    return v.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp });
  }

  function pivots(H, L, C, O, woodieOpen) {
    var range = H - L, out = {};
    var P = (H + L + C) / 3;
    out.classic = { P: P, R1: 2 * P - L, S1: 2 * P - H, R2: P + range, S2: P - range,
                    R3: H + 2 * (P - L), S3: L - 2 * (H - P) };
    var Pw = (H + L + 2 * (isFinite(woodieOpen) ? woodieOpen : C)) / 4;
    var R3w = H + 2 * (Pw - L), S3w = L - 2 * (H - Pw);
    out.woodie = { P: Pw, R1: 2 * Pw - L, S1: 2 * Pw - H, R2: Pw + range, S2: Pw - range,
                   R3: R3w, S3: S3w, R4: R3w + range, S4: S3w - range };
    out.camarilla = { P: P, R1: C + range * 1.1 / 12, S1: C - range * 1.1 / 12, R2: C + range * 1.1 / 6,
                      S2: C - range * 1.1 / 6, R3: C + range * 1.1 / 4, S3: C - range * 1.1 / 4,
                      R4: C + range * 1.1 / 2, S4: C - range * 1.1 / 2 };
    out.fibonacci = { P: P, R1: P + 0.382 * range, S1: P - 0.382 * range, R2: P + 0.618 * range,
                      S2: P - 0.618 * range, R3: P + range, S3: P - range };
    var X = C === O ? H + L + 2 * C : (C > O ? 2 * H + L + C : H + 2 * L + C);
    out.demark = { P: X / 4, R1: X / 2 - L, S1: X / 2 - H };
    return out;
  }

  var LABELS = { R4: 'Resistance 4 (R4)', R3: 'Resistance 3 (R3)', R2: 'Resistance 2 (R2)', R1: 'Resistance 1 (R1)',
                 P: 'Pivot point (P)', S1: 'Support 1 (S1)', S2: 'Support 2 (S2)', S3: 'Support 3 (S3)', S4: 'Support 4 (S4)' };

  function clear() {
    ['pvtStatP', 'pvtStatR1', 'pvtStatS1'].forEach(function (id) { document.getElementById(id).textContent = '–'; });
    ROWS.forEach(function (k) { document.getElementById('pvt' + k + 'Row').hidden = true; });
    document.getElementById('pvtTable').innerHTML = '';
  }

  function update() {
    var H = num('pvtHigh'), L = num('pvtLow'), C = num('pvtClose'), O = num('pvtOpen');
    var wOpen = blank('pvtWoodieOpen') ? NaN : num('pvtWoodieOpen');
    var method = document.getElementById('pvtMethod').value;
    var error = document.getElementById('pvtError');
    var msg = '';
    if ([H, L, C].some(isNaN)) msg = 'Enter the previous high, low and close.';
    else if (H < 0 || L < 0 || C < 0) msg = 'Prices cannot be negative.';
    else if (H < L) msg = 'The high must be at or above the low.';
    else if (C > H || C < L) msg = 'The close must be between the low and the high.';
    else if (!blank('pvtOpen') && (isNaN(O) || O < L || O > H)) msg = 'The previous open must be between the low and the high.';
    else if (blank('pvtOpen') && method === 'demark') msg = 'DeMark pivots need the previous open.';
    else if (!blank('pvtWoodieOpen') && (isNaN(wOpen) || wOpen < 0)) msg = 'The current open must be 0 or more, or leave it blank.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    var dp = Math.max(2, decimalsOf('pvtHigh'), decimalsOf('pvtLow'), decimalsOf('pvtClose'));
    var all = pivots(H, L, C, blank('pvtOpen') ? NaN : O, wOpen);
    var sel = all[method] || all.classic;
    document.getElementById('pvtStatP').textContent = fmt(sel.P, dp);
    document.getElementById('pvtStatR1').textContent = fmt(sel.R1, dp);
    document.getElementById('pvtStatS1').textContent = fmt(sel.S1, dp);
    ROWS.forEach(function (k) {
      var row = document.getElementById('pvt' + k + 'Row');
      var has = typeof sel[k] === 'number';
      row.hidden = !has;
      document.getElementById('pvt' + k).textContent = has ? fmt(sel[k], dp) : '–';
    });
    var showDemark = !blank('pvtOpen');
    document.getElementById('pvtTable').innerHTML = ROWS.map(function (k) {
      return '<tr><th scope="row">' + k + '</th>' + METHODS.map(function (m) {
        var v = all[m.key][k];
        if (m.key === 'demark' && !showDemark) v = undefined;
        return '<td>' + fmt(v, dp) + '</td>';
      }).join('') + '</tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('pvtForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
